import numpy as np
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from sklearn.metrics import roc_auc_score


def design(feats):
    ids = list(feats.ids)
    X = np.asarray(feats.x, float)
    y = np.asarray(feats.y, int)
    empty = Design(drivers=(), columns=(), products=(), loadings={})
    n, p = X.shape
    if p == 0 or n < 30 or len(np.unique(y)) < 2:
        return empty
    X = (X - X.mean(0)) / (X.std(0) + 1e-12)

    def welch(M, yv):  # signed Welch t per column of M vs binary yv
        a, b = M[yv == 1], M[yv == 0]
        return (a.mean(0) - b.mean(0)) / np.sqrt(
            a.var(0) / max(len(a), 1) + b.var(0) / max(len(b), 1) + 1e-12)

    def cv_auc(Xv, yv, sd, extra=()):  # selection inside each fold
        out = []
        for tr, te in StratifiedKFold(4, shuffle=True,
                                      random_state=sd).split(Xv, yv):
            pp = np.argsort(-np.abs(welch(Xv[tr], yv[tr])))[:min(12, p)]
            Xc = np.column_stack([Xv[:, pp]] + list(extra))
            m = LogisticRegression(C=1., max_iter=300).fit(Xc[tr], yv[tr])
            out.append(roc_auc_score(yv[te], m.predict_proba(Xc[te])[:, 1]))
        return float(np.mean(out))

    t = np.abs(welch(X, y)); order = np.argsort(-t)
    pool = list(order[:min(12, p)])
    prods, pcols, pw = [], [], {}  # all-pairs scan: joint-only mechanisms
    for a in range(p):
        for b in range(a + 1, p):
            tp = welch((X[:, a] * X[:, b]).reshape(-1, 1), y)[0]
            if abs(tp) > 4.4:
                prods += [(a, b)]; pcols += [X[:, a] * X[:, b]]
                pw[a] = pw[b] = float(np.sign(tp))
    if not pool and not pcols:
        return empty
    # Gate: select-then-fit inside CV folds must beat the same pipeline on
    # permuted labels, else claim nothing.
    obs, obs_pool = cv_auc(X, y, 0, pcols), (cv_auc(X, y, 0) if pool else .5)
    rng, perms = np.random.RandomState(0), []
    for s in range(6):
        perms += [cv_auc(X, rng.permutation(y), s + 1, pcols)]
    if obs < .52 or obs <= max(perms) + .005:
        return empty
    bar = 1.4 if obs_pool > max(perms) + .005 else 2.0
    # Rank by joint coefficient size x marginal support; inside a tight
    # cluster only the strongest member survives (correlates dropped).
    coef = {}
    if pool:
        m = LogisticRegression(C=.5, max_iter=500).fit(X[:, pool], y)
        coef = dict(zip(pool, m.coef_[0]))
    score = {i: abs(coef[i]) * (.5 + t[i]) for i in pool}
    fl = .25 * max(score.values()) if score else 0.
    keep = []
    for i in sorted(pool, key=lambda i: -score[i]):
        if score[i] < fl or t[i] < bar:
            break
        if all(abs(np.dot(X[:, i], X[:, j])) / n < .7 for j in keep):
            keep += [i]
        if len(keep) >= min(6, MAX_DRIVERS):
            break
    front = list(dict.fromkeys(i for ab in prods for i in ab))
    keep = (front + [i for i in keep if i not in front])[:MAX_DRIVERS]
    if not keep:
        return empty
    raw = {i: coef.get(i, pw.get(i, 1.)) for i in keep}
    mx = max(abs(v) for v in raw.values()) or 1.
    return Design(drivers=tuple(ids[i] for i in keep),
                  columns=tuple(ids[i] for i in keep),
                  products=tuple((ids[a], ids[b]) for a, b in prods[:4]),
                  loadings={ids[i]: float(v / mx) for i, v in raw.items()}
                  if len(keep) > 1 else {})

